SELECT ?s ?name ?p WHERE {
  ?s ?p ?o .
  ?s ref:hasTimeseriesId ?tid .
  FILTER (LCASE(STR(?s)) LIKE "%ahu01%" OR LCASE(STR(?s)) LIKE "%condpump02%" OR LCASE(STR(?s)) LIKE "%hwump01%")
}
LIMIT 200

SELECT ?s ?p WHERE {
  ?s ?p ?o .
  ?s ref:hasTimeseriesId ?tid .
  FILTER regex(str(?s), "AHU01|CondPump02|HWPump01", "i")
}
LIMIT 200

