import csv
with open(CATALOG_CSV) as f:
    rows=list(csv.DictReader(f))
for r in rows:
    u=r['point_uri']
    if any(x in u for x in ["AHU01","CondPump02","HWPump01"]):
        if "Power" in r['point_class'] or "Meter" in r['point_class']:
            print(r['timeseries_id'], r['point_class'], r['unit'], u)
